CREATE TABLE "Auditorias" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UsuarioId" uuid,
    "Actor" character varying(120) NOT NULL,
    "Entidad" character varying(80) NOT NULL,
    "RegistroId" character varying(80) NOT NULL,
    "Accion" character varying(40) NOT NULL,
    "Cambios" text NOT NULL,
    "Fecha" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Auditorias" PRIMARY KEY ("Id")
);


CREATE TABLE "Empleadores" (
    "Id" uuid NOT NULL,
    "Rut" character varying(9) NOT NULL,
    "Nombre" character varying(2000) NOT NULL,
    "Direccion" character varying(2000) NOT NULL,
    "Comuna" character varying(2000) NOT NULL,
    "Telefono" character varying(2000),
    "ActividadEconomica" character varying(2000),
    "Propiedad" character varying(2000),
    "TipoEmpresa" character varying(2000),
    "ActividadPrincipal" character varying(2000),
    CONSTRAINT "PK_Empleadores" PRIMARY KEY ("Id")
);


CREATE TABLE "Establecimientos" (
    "Id" uuid NOT NULL,
    "Nombre" character varying(120) NOT NULL,
    "Direccion" character varying(200) NOT NULL,
    "Activo" boolean NOT NULL,
    CONSTRAINT "PK_Establecimientos" PRIMARY KEY ("Id")
);


CREATE TABLE "Trabajadores" (
    "Id" uuid NOT NULL,
    "FechaIngreso" character varying(2000),
    "Antiguedad" integer,
    "AntiguedadUnidad" character varying(2000),
    "TipoContrato" character varying(2000),
    "TipoIngreso" character varying(2000),
    "CategoriaOcupacional" character varying(2000),
    "Codigo" character varying(30) NOT NULL,
    "Nombre" character varying(120) NOT NULL,
    "Cargo" character varying(100) NOT NULL,
    "Run" character varying(9),
    "Direccion" character varying(2000),
    "Comuna" character varying(2000),
    "Telefono" character varying(2000),
    "Sexo" character varying(2000),
    "FechaNacimiento" date,
    "Nacionalidad" character varying(2000),
    "PuebloOriginario" character varying(2000),
    "OtroPueblo" character varying(2000),
    "EstablecimientoId" uuid NOT NULL,
    "Activo" boolean NOT NULL,
    CONSTRAINT "PK_Trabajadores" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Trabajadores_Establecimientos_EstablecimientoId" FOREIGN KEY ("EstablecimientoId") REFERENCES "Establecimientos" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Usuarios" (
    "Id" uuid NOT NULL,
    "Nombre" character varying(120) NOT NULL,
    "Cuenta" character varying(50) NOT NULL,
    "PasswordHash" character varying(500) NOT NULL,
    "Rol" character varying(20) NOT NULL,
    "EstablecimientoId" uuid,
    "Activo" boolean NOT NULL,
    "Fallos" integer NOT NULL,
    "BloqueadoHasta" timestamp with time zone,
    CONSTRAINT "PK_Usuarios" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Usuarios_Rol" CHECK ("Rol" IN ('Administrador','Prevencion','Jefatura') AND ("Rol" <> 'Jefatura' OR "EstablecimientoId" IS NOT NULL)),
    CONSTRAINT "FK_Usuarios_Establecimientos_EstablecimientoId" FOREIGN KEY ("EstablecimientoId") REFERENCES "Establecimientos" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Casos" (
    "Id" uuid NOT NULL,
    "Codigo" character varying(32) NOT NULL,
    "Tipo" integer NOT NULL,
    "Establecimiento" character varying(120) NOT NULL,
    "Fecha" date NOT NULL,
    "Relato" character varying(5000) NOT NULL,
    "DenunciaJson" text,
    "EmpleadorId" uuid,
    "FechaEmision" date,
    "CodigoOrganismo" character varying(2000),
    "Folio" character varying(2000),
    "DenuncianteNombre" character varying(2000),
    "DenuncianteRun" character varying(2000),
    "DenuncianteTelefono" character varying(2000),
    "DenuncianteClasificacion" character varying(2000),
    "FirmaNombre" character varying(2000),
    "Estado" integer NOT NULL,
    "CreadoEn" timestamp with time zone NOT NULL,
    "EstablecimientoId" uuid,
    "TrabajadorId" uuid,
    "CerradoEn" timestamp with time zone,
    CONSTRAINT "PK_Casos" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Casos_Establecimiento" CHECK (LENGTH(TRIM("Establecimiento")) >= 3),
    CONSTRAINT "CK_Casos_Estado" CHECK ("Estado" IN (0, 1, 2, 3)),
    CONSTRAINT "CK_Casos_Relato" CHECK (LENGTH(TRIM("Relato")) >= 20),
    CONSTRAINT "CK_Casos_Tipo" CHECK ("Tipo" IN (0, 1)),
    CONSTRAINT "FK_Casos_Empleadores_EmpleadorId" FOREIGN KEY ("EmpleadorId") REFERENCES "Empleadores" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Casos_Establecimientos_EstablecimientoId" FOREIGN KEY ("EstablecimientoId") REFERENCES "Establecimientos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Casos_Trabajadores_TrabajadorId" FOREIGN KEY ("TrabajadorId") REFERENCES "Trabajadores" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Causas" (
    "Id" uuid NOT NULL,
    "CasoId" uuid NOT NULL,
    "Categoria" character varying(80) NOT NULL,
    "Descripcion" character varying(1000) NOT NULL,
    CONSTRAINT "PK_Causas" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Causas_Casos_CasoId" FOREIGN KEY ("CasoId") REFERENCES "Casos" ("Id") ON DELETE CASCADE
);


CREATE TABLE "DIAT" (
    "Id" uuid NOT NULL,
    "CasoId" uuid NOT NULL,
    "HoraAccidente" time without time zone,
    "HoraIngreso" time without time zone,
    "HoraSalida" time without time zone,
    "AccidenteDireccion" character varying(2000),
    "AccidenteComuna" character varying(2000),
    "ActividadAccidente" character varying(2000),
    "LugarAccidente" character varying(2000),
    "TrabajoHabitual" character varying(2000),
    "RealizabaHabitual" character varying(2000),
    "ClasificacionAccidente" character varying(2000),
    "TipoAccidente" character varying(2000),
    "TipoTrayecto" character varying(2000),
    "MedioPrueba" character varying(2000),
    "DetallePrueba" character varying(2000),
    CONSTRAINT "PK_DIAT" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_DIAT_Casos_CasoId" FOREIGN KEY ("CasoId") REFERENCES "Casos" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "DIEP" (
    "Id" uuid NOT NULL,
    "CasoId" uuid NOT NULL,
    "DuracionSintomas" integer,
    "DuracionSintomasUnidad" character varying(2000),
    "MolestiasPrevias" character varying(2000),
    "ParteCuerpo" character varying(2000),
    "ActividadSintomas" character varying(2000),
    "PuestoSintomas" character varying(2000),
    "CompanerosSintomas" character varying(2000),
    "Agentes" character varying(2000),
    "TiempoExposicion" integer,
    "TiempoExposicionUnidad" character varying(2000),
    CONSTRAINT "PK_DIEP" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_DIEP_Casos_CasoId" FOREIGN KEY ("CasoId") REFERENCES "Casos" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Investigaciones" (
    "Id" uuid NOT NULL,
    "CasoId" uuid NOT NULL,
    "Estado" character varying(20) NOT NULL,
    "Antecedentes" text NOT NULL,
    "RelatoFinal" character varying(10000) NOT NULL,
    "IniciadaEn" timestamp with time zone NOT NULL,
    "ActualizadaEn" timestamp with time zone NOT NULL,
    "CerradaEn" timestamp with time zone,
    "PlanIniciadoEn" timestamp with time zone,
    "EsHistorica" boolean NOT NULL,
    "Version" bytea NOT NULL DEFAULT BYTEA E'\\x',
    CONSTRAINT "PK_Investigaciones" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Investigaciones_Estado" CHECK ("Estado" IN ('EnCurso','Cerrada','Historica')),
    CONSTRAINT "FK_Investigaciones_Casos_CasoId" FOREIGN KEY ("CasoId") REFERENCES "Casos" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Observaciones" (
    "Id" uuid NOT NULL,
    "CasoId" uuid NOT NULL,
    "UsuarioId" uuid NOT NULL,
    "Autor" character varying(120) NOT NULL,
    "Texto" character varying(2000) NOT NULL,
    "Fecha" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Observaciones" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Observaciones_Casos_CasoId" FOREIGN KEY ("CasoId") REFERENCES "Casos" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Observaciones_Usuarios_UsuarioId" FOREIGN KEY ("UsuarioId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Entrevistas" (
    "Id" uuid NOT NULL,
    "InvestigacionId" uuid NOT NULL,
    "Entrevistado" character varying(120) NOT NULL,
    "Calidad" character varying(30) NOT NULL,
    "Fecha" date NOT NULL,
    "Declaracion" character varying(5000) NOT NULL,
    CONSTRAINT "PK_Entrevistas" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Entrevistas_Investigaciones_InvestigacionId" FOREIGN KEY ("InvestigacionId") REFERENCES "Investigaciones" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Evidencias" (
    "Id" uuid NOT NULL,
    "InvestigacionId" uuid,
    "CasoId" uuid NOT NULL,
    "Nombre" character varying(180) NOT NULL,
    "Tipo" character varying(80) NOT NULL,
    "Ruta" character varying(300) NOT NULL,
    "Tamano" bigint NOT NULL,
    "Sha256" character varying(64) NOT NULL,
    "UsuarioId" uuid NOT NULL,
    "Fecha" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Evidencias" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Evidencias_Metadatos" CHECK ("Tamano" BETWEEN 8 AND 5242880 AND LENGTH("Ruta") > 0 AND LENGTH("Sha256") = 64),
    CONSTRAINT "FK_Evidencias_Casos_CasoId" FOREIGN KEY ("CasoId") REFERENCES "Casos" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Evidencias_Investigaciones_InvestigacionId" FOREIGN KEY ("InvestigacionId") REFERENCES "Investigaciones" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Evidencias_Usuarios_UsuarioId" FOREIGN KEY ("UsuarioId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Hechos" (
    "Id" uuid NOT NULL,
    "InvestigacionId" uuid NOT NULL,
    "Descripcion" character varying(1000) NOT NULL,
    "EsFinal" boolean NOT NULL,
    CONSTRAINT "PK_Hechos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Hechos_Investigaciones_InvestigacionId" FOREIGN KEY ("InvestigacionId") REFERENCES "Investigaciones" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "MedidasInvestigacion" (
    "Id" uuid NOT NULL,
    "InvestigacionId" uuid NOT NULL,
    "HechoId" uuid,
    "Descripcion" character varying(1000) NOT NULL,
    "UsuarioResponsableId" uuid NOT NULL,
    "Responsable" character varying(120) NOT NULL,
    "Plazo" date NOT NULL,
    CONSTRAINT "PK_MedidasInvestigacion" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_MedidasInvestigacion_Hechos_HechoId" FOREIGN KEY ("HechoId") REFERENCES "Hechos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_MedidasInvestigacion_Investigaciones_InvestigacionId" FOREIGN KEY ("InvestigacionId") REFERENCES "Investigaciones" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_MedidasInvestigacion_Usuarios_UsuarioResponsableId" FOREIGN KEY ("UsuarioResponsableId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "RelacionesCausales" (
    "Id" uuid NOT NULL,
    "InvestigacionId" uuid NOT NULL,
    "AntecedenteId" uuid NOT NULL,
    "ConsecuenciaId" uuid NOT NULL,
    CONSTRAINT "PK_RelacionesCausales" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Relaciones_NoAutoRelacion" CHECK ("AntecedenteId" <> "ConsecuenciaId"),
    CONSTRAINT "FK_RelacionesCausales_Hechos_AntecedenteId" FOREIGN KEY ("AntecedenteId") REFERENCES "Hechos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_RelacionesCausales_Hechos_ConsecuenciaId" FOREIGN KEY ("ConsecuenciaId") REFERENCES "Hechos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_RelacionesCausales_Investigaciones_InvestigacionId" FOREIGN KEY ("InvestigacionId") REFERENCES "Investigaciones" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Medidas" (
    "Id" uuid NOT NULL,
    "Activa" boolean NOT NULL DEFAULT TRUE,
    "PropuestaId" uuid,
    "CasoId" uuid NOT NULL,
    "Descripcion" character varying(1000) NOT NULL,
    "Responsable" character varying(120) NOT NULL,
    "Plazo" date NOT NULL,
    "Completada" boolean NOT NULL,
    "UsuarioResponsableId" uuid,
    "ImplementadaEn" timestamp with time zone,
    "ComentarioCumplimiento" character varying(2000),
    "RevisadaEn" timestamp with time zone,
    "RevisorId" uuid,
    "Revision" character varying(2000),
    CONSTRAINT "PK_Medidas" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Medidas_Descripcion" CHECK (LENGTH(TRIM("Descripcion")) >= 10),
    CONSTRAINT "CK_Medidas_Responsable" CHECK (LENGTH(TRIM("Responsable")) >= 3),
    CONSTRAINT "FK_Medidas_Casos_CasoId" FOREIGN KEY ("CasoId") REFERENCES "Casos" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Medidas_MedidasInvestigacion_PropuestaId" FOREIGN KEY ("PropuestaId") REFERENCES "MedidasInvestigacion" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Medidas_Usuarios_UsuarioResponsableId" FOREIGN KEY ("UsuarioResponsableId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "EvidenciasMedidas" (
    "Id" uuid NOT NULL,
    "MedidaId" uuid NOT NULL,
    "UsuarioId" uuid NOT NULL,
    "Fecha" timestamp with time zone NOT NULL,
    "Nombre" character varying(180) NOT NULL,
    "Tipo" character varying(80) NOT NULL,
    "Ruta" character varying(300) NOT NULL,
    "Tamano" bigint NOT NULL,
    "Sha256" character varying(64) NOT NULL,
    CONSTRAINT "PK_EvidenciasMedidas" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_EvidenciasMedidas_Metadatos" CHECK ("Tamano" BETWEEN 8 AND 5242880 AND LENGTH("Ruta") > 0 AND LENGTH("Sha256") = 64),
    CONSTRAINT "FK_EvidenciasMedidas_Medidas_MedidaId" FOREIGN KEY ("MedidaId") REFERENCES "Medidas" ("Id") ON DELETE RESTRICT
);


CREATE INDEX "IX_Auditorias_Fecha" ON "Auditorias" ("Fecha");


CREATE UNIQUE INDEX "IX_Casos_Codigo" ON "Casos" ("Codigo");


CREATE INDEX "IX_Casos_EmpleadorId" ON "Casos" ("EmpleadorId");


CREATE INDEX "IX_Casos_EstablecimientoId" ON "Casos" ("EstablecimientoId");


CREATE INDEX "IX_Casos_Estado_Fecha" ON "Casos" ("Estado", "Fecha");


CREATE INDEX "IX_Casos_TrabajadorId" ON "Casos" ("TrabajadorId");


CREATE INDEX "IX_Causas_CasoId" ON "Causas" ("CasoId");


CREATE UNIQUE INDEX "IX_DIAT_CasoId" ON "DIAT" ("CasoId");


CREATE UNIQUE INDEX "IX_DIEP_CasoId" ON "DIEP" ("CasoId");


CREATE UNIQUE INDEX "IX_Empleadores_Rut" ON "Empleadores" ("Rut");


CREATE INDEX "IX_Entrevistas_InvestigacionId" ON "Entrevistas" ("InvestigacionId");


CREATE UNIQUE INDEX "IX_Establecimientos_Nombre" ON "Establecimientos" ("Nombre");


CREATE INDEX "IX_Evidencias_CasoId" ON "Evidencias" ("CasoId");


CREATE INDEX "IX_Evidencias_InvestigacionId" ON "Evidencias" ("InvestigacionId");


CREATE UNIQUE INDEX "IX_Evidencias_Ruta" ON "Evidencias" ("Ruta");


CREATE INDEX "IX_Evidencias_UsuarioId" ON "Evidencias" ("UsuarioId");


CREATE INDEX "IX_EvidenciasMedidas_MedidaId" ON "EvidenciasMedidas" ("MedidaId");


CREATE UNIQUE INDEX "IX_EvidenciasMedidas_Ruta" ON "EvidenciasMedidas" ("Ruta");


CREATE UNIQUE INDEX "IX_Hechos_InvestigacionId" ON "Hechos" ("InvestigacionId") WHERE "EsFinal" = true;


CREATE UNIQUE INDEX "IX_Investigaciones_CasoId" ON "Investigaciones" ("CasoId");


CREATE INDEX "IX_Medidas_CasoId" ON "Medidas" ("CasoId");


CREATE UNIQUE INDEX "IX_Medidas_PropuestaId" ON "Medidas" ("PropuestaId") WHERE "PropuestaId" IS NOT NULL;


CREATE INDEX "IX_Medidas_UsuarioResponsableId" ON "Medidas" ("UsuarioResponsableId");


CREATE INDEX "IX_MedidasInvestigacion_HechoId" ON "MedidasInvestigacion" ("HechoId");


CREATE INDEX "IX_MedidasInvestigacion_InvestigacionId" ON "MedidasInvestigacion" ("InvestigacionId");


CREATE INDEX "IX_MedidasInvestigacion_UsuarioResponsableId" ON "MedidasInvestigacion" ("UsuarioResponsableId");


CREATE INDEX "IX_Observaciones_CasoId" ON "Observaciones" ("CasoId");


CREATE INDEX "IX_Observaciones_UsuarioId" ON "Observaciones" ("UsuarioId");


CREATE UNIQUE INDEX "IX_RelacionesCausales_AntecedenteId_ConsecuenciaId" ON "RelacionesCausales" ("AntecedenteId", "ConsecuenciaId");


CREATE INDEX "IX_RelacionesCausales_ConsecuenciaId" ON "RelacionesCausales" ("ConsecuenciaId");


CREATE INDEX "IX_RelacionesCausales_InvestigacionId" ON "RelacionesCausales" ("InvestigacionId");


CREATE UNIQUE INDEX "IX_Trabajadores_Codigo" ON "Trabajadores" ("Codigo");


CREATE INDEX "IX_Trabajadores_EstablecimientoId" ON "Trabajadores" ("EstablecimientoId");


CREATE UNIQUE INDEX "IX_Trabajadores_Run" ON "Trabajadores" ("Run") WHERE "Run" IS NOT NULL;


CREATE UNIQUE INDEX "IX_Usuarios_Cuenta" ON "Usuarios" ("Cuenta");


CREATE INDEX "IX_Usuarios_EstablecimientoId" ON "Usuarios" ("EstablecimientoId");


